// // Physics constants, world scanning and the behaviour planner for the roaming
// // pet. Everything here is pure and frame-rate independent (units are px and
// // px/second), so Pet.js only has to integrate it.

export const MODE = {
  WALK: "walk",
  SIT: "sit",
  GROOM: "groom",
  SCRATCH: "scratch",
  SLEEP: "sleep",
  FALL: "fall",
  CLIMB: "climb",
  CEILING: "ceiling",
  DRAG: "drag",
  LAND: "land",
  TALK: "talk",
};

export const SURFACE = {
  FLOOR: "floor",
  LEDGE: "ledge",
  WALL_L: "wall-l",
  WALL_R: "wall-r",
  CEILING: "ceiling",
  AIR: "air",
};

// px/second unless noted. Tuned for organic, fluid motion.
export const PHYS = {
  gravity: 1550,
  terminal: 1200,
  walk: 52,
  amble: 32,
  climb: 46,
  crawl: 40,
  airDrag: 0.42, // per second, horizontal deceleration in flight
  bounce: 0.38, // realistic elasticity against walls and floors
  throwScale: 1.18,
  maxThrow: 1500,
  dragLag: 0.24, // smooth spring lag trailing the pointer
};

export const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
export const rand = (lo, hi) => lo + Math.random() * (hi - lo);

const pick = (options) => {
  const total = options.reduce((sum, o) => sum + o.w, 0);
  let r = Math.random() * total;
  for (const o of options) {
    r -= o.w;
    if (r <= 0) return o;
  }
  return options[options.length - 1];
};

/* ------------------------------------------------------------------ */
/* World Scanning (Smart Furniture Detection)                          */
/* ------------------------------------------------------------------ */

// Scans real page elements so the pet perches on project cards, headings,
// and portfolio showcases.
const LEDGE_SELECTOR =
  "h1, h2, h3, h4, img, picture, button, article, section, blockquote, nav, header," +
  "[class*='card'], [class*='Card'], [class*='tile'], [class*='Tile'], [class*='project'], [class*='Project'], [data-ledge]";

const MIN_LEDGE_W = 120;
const MIN_LEDGE_H = 30;
const SCAN_CAP = 500;
const LEDGE_CAP = 16;

export const scanLedges = (vw, vh, margin) => {
  let nodes;
  try {
    nodes = document.querySelectorAll(LEDGE_SELECTOR);
  } catch (e) {
    return [];
  }

  const found = [];
  const limit = Math.min(nodes.length, SCAN_CAP);

  for (let i = 0; i < limit; i += 1) {
    const el = nodes[i];
    // Skip pet UI itself or elements marked to ignore
    if (el.closest("[data-pet-ignore]")) continue;

    // Skip non-rendered / hidden elements
    if (el.offsetParent === null && el.tagName !== "BODY") continue;

    const r = el.getBoundingClientRect();
    if (r.width < MIN_LEDGE_W || r.height < MIN_LEDGE_H) continue;
    if (r.width > vw * 0.96) continue; // page-width wrappers are not perches
    if (r.top < margin + 35 || r.top > vh - margin - 25) continue;

    found.push({ x1: r.left + 6, x2: r.right - 6, y: r.top, el });
  }

  // Filter out fixed/sticky overlays (headers, chat bubbles, navigation drawers)
  const solid = found.filter((l) => {
    let node = l.el;
    for (let hops = 0; node && hops < 6; hops += 1) {
      if (!node || node === document.body) break;
      const style = window.getComputedStyle(node);
      const pos = style.position;
      const display = style.display;
      const opacity = parseFloat(style.opacity || "1");
      if (
        pos === "fixed" ||
        pos === "sticky" ||
        display === "none" ||
        opacity === 0
      ) {
        return false;
      }
      node = node.parentElement;
    }
    return true;
  });

  // Collapse and merge overlapping horizontal ledges
  solid.sort((a, b) => a.y - b.y || a.x1 - b.x1);
  const merged = [];
  for (const l of solid) {
    const prev = merged[merged.length - 1];
    if (prev && Math.abs(prev.y - l.y) < 9 && l.x1 < prev.x2 + 24) {
      prev.x1 = Math.min(prev.x1, l.x1);
      prev.x2 = Math.max(prev.x2, l.x2);
    } else {
      merged.push({ x1: l.x1, x2: l.x2, y: l.y, el: l.el });
    }
  }

  return merged.filter((l) => l.x2 - l.x1 >= MIN_LEDGE_W).slice(0, LEDGE_CAP);
};

// Finds the ledge directly beneath coordinates. `skipEl` lets a caller ignore
// the ledge it has just deliberately stepped off, which would otherwise catch
// it again on the very next frame.
export const supportAt = (ledges, x, fromY, toY, skipEl) => {
  let best = null;
  for (const l of ledges) {
    if (skipEl && l.el === skipEl) continue;
    if (x < l.x1 || x > l.x2) continue;
    if (l.y < fromY - 0.5 || l.y > toY) continue;
    if (!best || l.y < best.y) best = l;
  }
  return best;
};

/* ------------------------------------------------------------------ */
/* Behaviour Planning                                                  */
/* ------------------------------------------------------------------ */

export const planNext = ({ surface, boredom, nearWall }) => {
  if (surface === SURFACE.WALL_L || surface === SURFACE.WALL_R) {
    const o = pick([
      { w: 4.5, mode: MODE.CLIMB, dir: -1 },
      { w: 1.5, mode: MODE.FALL },
      { w: 1.2, mode: MODE.FALL },
    ]);
    return { ...o, ms: o.mode === MODE.FALL ? 0 : rand(1400, 3200) };
  }

  if (surface === SURFACE.CEILING) {
    const o = pick([
      { w: 4.2, mode: MODE.CEILING, dir: Math.random() < 0.5 ? -1 : 1 },
      { w: 1.2, mode: MODE.SIT },
      { w: 2.0, mode: MODE.FALL },
    ]);
    return { ...o, ms: o.mode === MODE.FALL ? 0 : rand(1600, 3400) };
  }

  const onLedge = surface === SURFACE.LEDGE;

  const options = [
    { w: 5.2, mode: MODE.WALK, dir: Math.random() < 0.5 ? -1 : 1 },
    { w: 3.2, mode: MODE.SIT },
    { w: 2.2, mode: MODE.GROOM },
    { w: 1.6, mode: MODE.SCRATCH },
  ];

  if (onLedge) options.push({ w: 1.6, mode: MODE.FALL });

  // Climbing wall bias when close
  if (!onLedge && nearWall) options.push({ w: 2.8, mode: MODE.CLIMB, dir: -1 });

  // Sleep once genuinely idle
  if (boredom > 3) options.push({ w: 2.2 + boredom * 1.2, mode: MODE.SLEEP });

  const o = pick(options);
  const ms =
    o.mode === MODE.FALL
      ? 0
      : o.mode === MODE.SLEEP
      ? rand(10000, 22000)
      : o.mode === MODE.WALK
      ? rand(2400, 6200)
      : rand(2600, 6800);

  return { ...o, ms };
};

