// What the pet says when it notices the page underneath it has changed.
const PAGE_REACTIONS = {
  "/": ["a whole page to explore 🐾", "ooh, back to the top!"],
  "/home": ["home sweet home", "this is where it all starts"],
  "/projects": [
    "ooh, the projects shelf!",
    "so many cards to sit on 🐾",
    "he built all of these?",
  ],
  "/projects/detail": ["let's read this one", "ooh, a deep dive"],
  "/experience": ["look at all this experience", "résumé territory"],
  "/education": ["study time?", "smart human, this one"],
  "/contact": ["this is the part where you say hi 👋", "go on, email him!"],
  "/blog": ["stories! i'll nap while you read 📚", "bedtime reading"],
  "/jarvis": ["ooh, the fancy one", "JARVIS is showing off again"],
  "/myspace": ["the agents playground!", "robots. my nemesis."],
  "/jobhunt": ["hunting season 🎯"],
  "/github": ["code, code, code", "so many repos"],
  default: ["ooh, somewhere new 🐾", "what's over here then?"],
};

export const pageReaction = (pathname) => {
  const p = (pathname || "/").replace(/\/+$/, "") || "/";
  if (p.startsWith("/projects/")) return PAGE_REACTIONS["/projects/detail"];
  return PAGE_REACTIONS[p] || PAGE_REACTIONS.default;
};

const MAX_LABEL = 30;

// Reads whatever the pet has just landed on, so it can mention the thing by
// name instead of perching on it silently.
export const describePerch = (el) => {
  if (!el) return null;
  let text =
    el.getAttribute("alt") ||
    el.getAttribute("aria-label") ||
    el.getAttribute("title") ||
    "";
  if (!text && /^(H[1-4]|BUTTON|A)$/.test(el.tagName))
    text = el.textContent || "";
  if (!text) {
    const heading = el.querySelector("h1, h2, h3, h4");
    if (heading) text = heading.textContent || "";
  }
  text = text.replace(/\s+/g, " ").trim();
  if (text.length < 2) return null;
  return text.length > MAX_LABEL ? `${text.slice(0, MAX_LABEL - 1)}…` : text;
};
