import styled, { keyframes } from "styled-components";

// NOTE: Never use unescaped backticks inside CSS comments.

const isLight = (p) => p.theme?.name === "light";

const rim = (p) =>
  isLight(p)
    ? "drop-shadow(0 0 0.8px rgba(60, 24, 6, 0.45))"
    : "drop-shadow(0 0 0.8px rgba(20, 8, 2, 0.6))";

/* ------------------------------------------------------------------ */
/* Rig Motion Keyframes (Bio-Kinematic Quadruped Cycles)               */
/* ------------------------------------------------------------------ */

const upperSwing = keyframes`
  0%   { transform: rotate(22deg); }
  50%  { transform: rotate(-22deg); }
  100% { transform: rotate(22deg); }
`;

const lowerSwing = keyframes`
  0%   { transform: rotate(-18deg); }
  32%  { transform: rotate(4deg); }
  55%  { transform: rotate(18deg); }
  82%  { transform: rotate(-6deg); }
  100% { transform: rotate(-18deg); }
`;

const reachUpper = keyframes`
  0%   { transform: rotate(16deg); }
  50%  { transform: rotate(-16deg); }
  100% { transform: rotate(16deg); }
`;

const reachLower = keyframes`
  0%   { transform: rotate(-12deg); }
  50%  { transform: rotate(12deg); }
  100% { transform: rotate(-12deg); }
`;

const bodyBob = keyframes`
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50%      { transform: translateY(-2.8px) rotate(-0.8deg); }
`;

const headBob = keyframes`
  0%   { transform: translateY(-0.5px) rotate(0.5deg); }
  50%  { transform: translateY(0.6px) rotate(-0.45deg); }
  100% { transform: translateY(-0.5px) rotate(0.5deg); }
`;

/* ------------------------------------------------------------------ */
/* Dynamic Whip & Tremor Tail Physics Keyframes                       */
/* ------------------------------------------------------------------ */

// Base segment: Fluid, rhythmic swaying with organic overshoot
const tailSway = keyframes`
  0%   { transform: rotate(-18deg); }
  25%  { transform: rotate(-6deg); }
  50%  { transform: rotate(22deg); }
  75%  { transform: rotate(8deg); }
  100% { transform: rotate(-18deg); }
`;

// Tip segment: Phase-delayed wave propagation + snappy micro-whipping
const tailTip = keyframes`
  0%   { transform: rotate(18deg); }
  20%  { transform: rotate(-8deg); }
  45%  { transform: rotate(-24deg); }
  65%  { transform: rotate(6deg); }
  85%  { transform: rotate(26deg); }
  100% { transform: rotate(18deg); }
`;

// Seated / Idle / Inquisitive Tail: Restless tremors with sudden fast flicks
const tailFlick = keyframes`
  0%, 100% { transform: translate(2px, 26px) rotate(26deg); }
  15%      { transform: translate(2px, 26px) rotate(14deg); }
  25%      { transform: translate(2px, 26px) rotate(32deg); }
  35%      { transform: translate(2px, 26px) rotate(16deg); }
  45%      { transform: translate(2px, 26px) rotate(28deg); }
  55%      { transform: translate(2px, 26px) rotate(18deg); }
  68%      { transform: translate(2px, 26px) rotate(36deg); }
  74%      { transform: translate(2px, 26px) rotate(-8deg); } /* Fast inquisitive flick */
  82%      { transform: translate(2px, 26px) rotate(42deg); } /* Snappy recoil */
  90%      { transform: translate(2px, 26px) rotate(24deg); }
`;

// Quick tail tip twitch during sitting
const tailTipFlick = keyframes`
  0%, 100% { transform: rotate(-18deg); }
  30%      { transform: rotate(8deg); }
  50%      { transform: rotate(-26deg); }
  74%      { transform: rotate(34deg); }  /* Snaps in counter-direction */
  82%      { transform: rotate(-40deg); }
  92%      { transform: rotate(-12deg); }
`;

const earTwitch = keyframes`
  0%, 90%, 100% { transform: rotate(0deg); }
  93%           { transform: rotate(-11deg); }
  96%           { transform: rotate(5deg); }
`;

const groomLick = keyframes`
  0%, 100% { transform: translate(-7px, 2px) rotate(22deg); }
  50%      { transform: translate(-10px, 7px) rotate(29deg); }
`;

const scratchLeg = keyframes`
  0%   { transform: rotate(-58deg) translate(8px, -14px); }
  100% { transform: rotate(-68deg) translate(12px, -18px); }
`;

const breathe = keyframes`
  0%, 100% { transform: translateY(9px) scale(1, 1); }
  50%      { transform: translateY(10.5px) scale(1.03, 0.97); }
`;

// Chest rise and fall about the shoulder. Two variants because .pet-body
// carries a static pose transform in sit/talk that an animation would erase.
const breatheIdle = keyframes`
  0%, 100% { transform: scale(1, 1); }
  50%      { transform: scale(1.016, 0.986); }
`;

const breatheSit = keyframes`
  0%, 100% { transform: translateY(-2px) rotate(-30deg) scale(1, 1); }
  50%      { transform: translateY(-2.6px) rotate(-30deg) scale(1.016, 0.986); }
`;

const zFloat = keyframes`
  0%   { opacity: 0; transform: translate(0, 0) scale(0.6) rotate(-8deg); }
  25%  { opacity: 1; }
  100% { opacity: 0; transform: translate(16px, -30px) scale(1.1) rotate(14deg); }
`;

const popIn = keyframes`
  0%   { opacity: 0; transform: translateX(-50%) translateY(12px) scale(0.88); }
  65%  { opacity: 1; transform: translateX(-50%) translateY(-2px) scale(1.03); }
  100% { opacity: 1; transform: translateX(-50%) translateY(0) scale(1); }
`;

const dot = keyframes`
  0%, 80%, 100% { opacity: 0.3; transform: translateY(0); }
  40%           { opacity: 1;   transform: translateY(-3.5px); }
`;

/* ------------------------------------------------------------------ */
/* The Pet Layer & Interactive Rig                                     */
/* ------------------------------------------------------------------ */

export const PetLayer = styled.div`
  --stride: 700ms;
  --squish-x: 1;
  --squish-y: 1;
  --shadow-scale: 1;
  --shadow-op: 1;
  --flip: 1;

  position: fixed;
  top: 0;
  left: 0;
  width: ${(p) => p.w}px;
  height: ${(p) => p.h}px;
  z-index: 1150;
  transform-origin: ${(p) => p.w / 2}px ${(p) => p.h * 0.9}px;
  will-change: transform;
  pointer-events: none;
  touch-action: none;
`;

export const PetGrab = styled.button`
  appearance: none;
  border: 0;
  margin: 0;
  padding: 0;
  background: none;
  font: inherit;
  color: inherit;
  display: block;
  width: 100%;
  height: 100%;
  pointer-events: auto;
  cursor: grab;
  touch-action: none;
  -webkit-tap-highlight-color: transparent;

  /* Facing is applied here, not on PetLayer, so that layer children (the
     sleep "z"s) are never rendered back-to-front. */
  transform: scaleX(var(--flip, 1));
  transform-origin: 50% 90%;

  &:active {
    cursor: grabbing;
  }

  &:focus {
    outline: none;
  }

  &:focus-visible .pet-svg {
    filter: ${(p) => rim(p)}
      drop-shadow(0 0 4px ${(p) => (isLight(p) ? "#B45309" : "#FBBF24")})
      drop-shadow(
        0 0 10px
          ${(p) =>
            isLight(p) ? "rgba(180, 83, 9, 0.4)" : "rgba(251, 191, 36, 0.5)"}
      );
  }

  .pet-svg {
    display: block;
    width: 100%;
    height: 100%;
    overflow: visible;
    /* A hairline of shadow hugging the silhouette, so a ginger cat keeps its
       shape on warm or busy backgrounds and on the white light theme --
       without drawing a cartoon outline. */
    filter: ${(p) => rim(p)};
  }

  .pet-head-tilt {
    transform-box: view-box;
    transform-origin: 110px 52px;
    transform: rotate(var(--head-tilt, 0deg));
  }

  /* Rig geometry with dynamic squash & stretch */
  .pet-rig {
    transform-box: view-box;
    transform-origin: 72px 108px;
    transform: scale(var(--squish-x, 1), var(--squish-y, 1));
    transition: transform 0.08s cubic-bezier(0.25, 1, 0.5, 1);
  }

  .pet-leg,
  .seg-lower,
  .pet-tail,
  .pet-tail-tip,
  .pet-head,
  .pet-ears,
  .pet-body,
  .pet-ear,
  .pet-neck,
  .pet-collar,
  .pet-shadow,
  .pet-eye,
  .pet-face {
    transform-box: view-box;
  }

  .pet-body {
    transform-origin: 100px 58px;
  }
  .pet-head,
  .pet-neck,
  .pet-collar {
    transform-origin: 102px 58px;
  }
  .pet-ears {
    transform-origin: 124px 30px;
    /* Secondary motion: ears swing back under acceleration and overshoot on
       stop. Written by the loop as --ear-lag. */
    transform: rotate(var(--ear-lag, 0deg));
  }
  .ear-near {
    transform-origin: 115px 28px;
  }
  .ear-far {
    transform-origin: 133px 26px;
  }
  .pet-tail {
    transform-origin: 40px 70px;
  }
  .pet-tail-tip {
    transform-origin: 9px 44px;
  }
  /* Tail physics, written by the loop: the base swings about the rump and the
     tip about the joint, each a damped spring, so the tip whips after the
     base. No transition -- the springs already are the smoothing. */
  .pet-tail-phys,
  .pet-tail-tip-phys {
    transform-box: view-box;
  }
  .pet-tail-phys {
    transform-origin: 40px 70px;
    transform: rotate(var(--tail-lag, 0deg));
  }
  .pet-tail-tip-phys {
    transform-origin: 9px 44px;
    transform: rotate(var(--tail-tip-lag, 0deg));
  }

  .lb-near {
    transform-origin: 48px 68px;
  }
  .lb-near .seg-lower {
    transform-origin: 37px 89px;
  }
  .lb-far {
    transform-origin: 42px 68px;
  }
  .lb-far .seg-lower {
    transform-origin: 33px 88px;
  }
  .lf-near {
    transform-origin: 96px 70px;
  }
  .lf-near .seg-lower {
    transform-origin: 97px 89px;
  }
  .lf-far {
    transform-origin: 89px 70px;
  }
  .lf-far .seg-lower {
    transform-origin: 90px 89px;
  }

  .pet-leg,
  .seg-lower,
  .pet-body,
  .pet-head,
  .pet-tail,
  .pet-tail-tip,
  .pet-neck,
  .pet-collar,
  .pet-ear {
    transition: transform 0.32s cubic-bezier(0.34, 1.35, 0.64, 1);
  }

  /* Screen-space relight: cancels the parent mirror so the lit side and the
     shaded side stay on the same side of the screen whichever way it faces. */
  .pet-relight {
    transform-box: view-box;
    transform-origin: 80px 60px;
    transform: scaleX(var(--flip, 1));
    pointer-events: none;
  }

  /* ---- 4. Far limbs sit further away: slightly smaller, lifted, and pushed
     back, so the two leg pairs read as separated in depth rather than as one
     silhouette in two colours. */
  .pet-legs-far {
    transform-box: view-box;
    transform-origin: 63px 70px;
    transform: scale(0.92) translate(-3px, -1px);
    opacity: 0.86;
  }

  /* ---- 5. Blink lid: 0 = open (parked above the eye), 1 = fully drawn.
     The crease fades in with it, so a shut eye reads as a line rather than a
     blank patch of skin. */
  .pet-lid {
    transform-box: view-box;
    transform: translateY(calc(var(--lid, 0) * 16px));
  }
  .pet-lash {
    opacity: var(--lid, 0);
  }

  /* Floor Shadow Scaling */
  .pet-shadow {
    transform-origin: 72px 110px;
    transform: scale(var(--shadow-scale, 1));
    opacity: var(--shadow-op, 1);
    transition: opacity 0.2s ease, transform 0.2s ease;
  }

  .pet-pupil {
    transition: rx 0.35s ease, ry 0.35s ease;
  }
  /* Excited: pupils widen while a cursor is darting about close by. Set by
     the loop on the svg; the drag, fall and talk rules below still win. */
  .pet-svg[data-excited="1"] {
    .eye-near .pet-pupil {
      rx: 3.6px;
    }
    .eye-far .pet-pupil {
      rx: 2.8px;
    }
  }

  /* --- Anatomical Profile vs 3/4 Face View --- */
  .eye-far,
  .pad-far,
  .wk-rear {
    transform-box: view-box;
    transition: opacity 0.28s ease, transform 0.28s ease;
  }
  .eye-far {
    transform-origin: 113px 40.5px;
  }
  .pad-far {
    transform-origin: 130px 56px;
  }
  .eye-near {
    transform-box: view-box;
    transform-origin: 135px 39.6px;
    transition: transform 0.28s ease;
  }

  /* When walking and looking ahead (pure side profile):
     1. Far eye hides behind the curved skull.
     2. Near eye foreshortens realistically toward the muzzle. */
  .pet-svg[data-look="profile"] {
    .eye-far {
      opacity: 0;
      transform: translateX(12px) scaleX(0.1);
      pointer-events: none;
    }
    .pad-far {
      opacity: 0.1;
      transform: translateX(6px) scaleX(0.4);
    }
    .wk-rear {
      opacity: 0;
    }
    .eye-near {
      transform: translateX(4px) scaleX(0.65) rotate(-3deg);
    }
  }

  /* --- WALK Cycle --- */
  .pet-svg[data-pose="walk"] {
    .pet-leg {
      transition: none;
      animation: ${upperSwing} var(--stride) ease-in-out infinite;
    }
    .pet-leg .seg-lower {
      transition: none;
      animation: ${lowerSwing} var(--stride) linear infinite;
    }
    .lf-far,
    .lf-far .seg-lower,
    .lb-near,
    .lb-near .seg-lower {
      animation-delay: calc(var(--stride) / -2);
    }
    .pet-body {
      animation: ${bodyBob} calc(var(--stride) / 2) ease-in-out infinite;
    }
    .pet-head {
      animation: ${headBob} calc(var(--stride) / 2) ease-in-out infinite;
    }

    /* Wave Physics: Tip lags base by ~35% of the stride cycle */
    .pet-tail {
      animation: ${tailSway} calc(var(--stride) * 1.5)
        cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite;
    }
    .pet-tail-tip {
      animation: ${tailTip} calc(var(--stride) * 1.5)
        cubic-bezier(0.25, 0.1, 0.25, 1) infinite;
      animation-delay: calc(var(--stride) * -0.42); /* Wave propagation delay */
    }
    .ear-near {
      animation: ${earTwitch} 8.5s ease-in-out infinite;
    }
  }
  .pet-svg[data-pose="sit"],
  .pet-svg[data-pose="talk"] {
    .pet-body {
      transform: translateY(-2px) rotate(-30deg);
      animation: ${breatheSit} 4.4s ease-in-out infinite;
    }
    .lb-near {
      transform: translate(12px, 25px) rotate(-135deg);
    }
    .lb-near .seg-lower {
      transform: rotate(175deg);
    }
    .lb-far {
      transform: translate(10px, 24px) rotate(-133deg);
    }
    .lb-far .seg-lower {
      transform: rotate(173deg);
    }
    .lf-near,
    .lf-far {
      transform: rotate(-1deg);
    }
    .pet-head,
    .pet-neck,
    .pet-collar {
      transform: translate(1px, -4px) rotate(-4deg);
    }

    /* Restless twitching & shaky inquisitive tail */
    .pet-tail {
      animation: ${tailFlick} 4.2s cubic-bezier(0.35, 1.4, 0.65, 1) infinite;
    }
    .pet-tail-tip {
      animation: ${tailTipFlick} 4.2s cubic-bezier(0.34, 1.56, 0.64, 1) infinite;
      animation-delay: -0.15s;
    }
    .ear-near {
      animation: ${earTwitch} 7s ease-in-out infinite;
    }
  }
  .pet-svg[data-pose="groom"],
  .pet-svg[data-pose="scratch"],
  .pet-svg[data-pose="land"] {
    .pet-body {
      animation: ${breatheIdle} 4.4s ease-in-out infinite;
    }
  }

  .pet-svg[data-pose="groom"] {
    /* Near front paw lifts to the mouth while other 3 legs stay planted */
    .lf-near {
      transform: rotate(-45deg);
    }
    .lf-near .seg-lower {
      transform: rotate(-35deg);
    }
    .pet-head,
    .pet-neck,
    .pet-collar {
      animation: ${groomLick} 1s ease-in-out infinite;
    }
  }

  .pet-svg[data-pose="scratch"] {
    /* Near hind leg raises to scratch ear while remaining legs support */
    .lb-near {
      transform: translate(38px, -14px) rotate(-18deg);
    }
    .lb-near .seg-lower {
      transition: none;
      animation: ${scratchLeg} 0.12s ease-in-out infinite alternate;
    }
    .pet-head,
    .pet-neck,
    .pet-collar {
      transform: translate(1px, 2px) rotate(-9deg);
    }
    .ear-near {
      transform: rotate(-15deg);
    }
  }
  .pet-svg[data-pose="talk"] {
    .ear-near {
      transform: rotate(-6deg) translateY(-1px);
    }
    .ear-far {
      transform: rotate(6deg) translateY(-1px);
    }
    .eye-near .pet-pupil {
      rx: 3px;
    }
    .eye-far .pet-pupil {
      rx: 2.4px;
    }
  }

  /* --- SLEEP --- */
  .pet-svg[data-pose="sleep"] {
    .pet-rig {
      animation: ${breathe} 4.2s ease-in-out infinite;
    }
    .pet-body {
      transform: translateY(20px) scale(1.07, 0.78);
    }
    .pet-leg {
      opacity: 0;
    }
    .pet-head,
    .pet-neck,
    .pet-collar {
      transform: translate(-10px, 26px) rotate(8deg);
    }
    .pet-tail {
      transform: translate(12px, 27px) rotate(104deg);
    }
    .pet-tail-tip {
      transform: rotate(-56deg);
    }
    .ear-near {
      transform: rotate(-30deg);
    }
    .ear-far {
      transform: rotate(24deg);
    }
    .pet-whiskers {
      opacity: 0.35;
    }
  }

  /* --- AIRBORNE --- */
  .pet-svg[data-pose="fall"] {
    .pet-body {
      transform: rotate(4deg);
    }
    .lf-near,
    .lf-far {
      transform: rotate(-58deg);
    }
    .lf-near .seg-lower,
    .lf-far .seg-lower {
      transform: rotate(-38deg);
    }
    .lb-near,
    .lb-far {
      transform: rotate(52deg);
    }
    .lb-near .seg-lower,
    .lb-far .seg-lower {
      transform: rotate(46deg);
    }
    .pet-tail {
      transform: rotate(-34deg);
    }
    .pet-tail-tip {
      transform: rotate(32deg);
    }
    .ear-near {
      transform: rotate(-30deg);
    }
    .ear-far {
      transform: rotate(26deg);
    }
    .eye-near .pet-pupil {
      rx: 5px;
    }
    .eye-far .pet-pupil {
      rx: 4px;
    }
  }

  .pet-svg[data-pose="drag"] {
    .pet-body {
      transform: rotate(8deg);
    }
    .lf-near,
    .lf-far {
      transform: rotate(-14deg);
    }
    .lb-near,
    .lb-far {
      transform: rotate(-26deg);
    }
    .lb-near .seg-lower,
    .lb-far .seg-lower {
      transform: rotate(26deg);
    }
    .pet-leg .seg-lower {
      transform: rotate(6deg);
    }
    .pet-head,
    .pet-neck,
    .pet-collar {
      transform: rotate(6deg);
    }
    .pet-tail {
      transform: rotate(-58deg);
    }
    .pet-tail-tip {
      transform: rotate(34deg);
    }
    .ear-near {
      transform: rotate(-22deg);
    }
    .ear-far {
      transform: rotate(20deg);
    }
    .eye-near .pet-pupil {
      rx: 4.2px;
    }
  }

  .pet-svg[data-pose="climb"],
  .pet-svg[data-pose="ceiling"] {
    .pet-leg {
      transition: none;
      animation: ${reachUpper} var(--stride) ease-in-out infinite;
    }
    .pet-leg .seg-lower {
      transition: none;
      animation: ${reachLower} var(--stride) ease-in-out infinite;
    }
    .lf-far,
    .lf-far .seg-lower,
    .lb-near,
    .lb-near .seg-lower {
      animation-delay: calc(var(--stride) / -2);
    }
    .pet-tail {
      transform: rotate(-16deg);
      animation: ${tailSway} calc(var(--stride) * 2.2) ease-in-out infinite;
    }
  }

  .pet-svg[data-pose="land"] {
    .pet-leg {
      transform: rotate(6deg);
    }
    .pet-leg .seg-lower {
      transform: rotate(-12deg);
    }
  }

  .pet-svg[data-reduce="1"],
  .pet-svg[data-reduce="1"] * {
    animation: none !important;
    transition: none !important;
  }
`;

export const Zzz = styled.span`
  position: absolute;
  top: 6px;
  left: 8px;
  font-size: 14px;
  font-weight: 700;
  pointer-events: none;
  color: ${(p) => (isLight(p) ? "#7C4A21" : "#FCD9A8")};
  animation: ${zFloat} 2.8s ease-out infinite;
  animation-delay: ${(p) => p.delay}s;
  opacity: 0;
`;

