import React, {
  lazy,
  Suspense,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { useLocation } from "react-router-dom";
import { useTheme } from "styled-components";
import PetSprite from "./PetSprite";
import {
  MODE,
  PHYS,
  REACTIONS,
  SURFACE,
  clamp,
  describePerch,
  pageReaction,
  planNext,
  rand,
  sayOneOf,
  scanLedges,
  supportAt,
} from "./PetBehaviour";
import {
  Bubble,
  BubbleLayer,
  HintLines,
  PetGrab,
  PetLayer,
  VisuallyHidden,
  Zzz,
} from "./Pet.styles";

// The language model half is a separate chunk that only mounts once someone
// actually interrupts the pet. Left alone it is pure physics -- no microphone,
// no engine, no network.
const PetBrain = lazy(() => import("./PetBrain"));

const NAME = "Mochi";

// How many times the drag hint may appear in one page load, for someone who
// has never dragged the pet.
const HINT_MAX = 3;
const HINT_SEEN_KEY = "mochi:drag-known";
// 4:3, matching the 160x120 sprite viewBox. There is no mobile size any more:
// ChatBot gates the pet behind a laptop-width, fine-pointer media query, so it
// never mounts on a screen small enough to need one.
const SIZE = { w: 104, h: 78 };
const FOOT = 0.9; // paws sit at y=108 of the 120-unit sprite box
const MARGIN = 8;
const TAP_MS = 350;
const TAP_SLOP = 7;
const RESCAN_MS = 4000;
const DEG_T = Math.PI / 180;

// Scripted arrival on the landing page: drop onto his name, have a look, then
// hop down onto the "Try Coding AI agent" button. The first anchor is a <span>,
// which scanLedges deliberately ignores, so the intro carries its own anchor
// collision rather than relying on the furniture map.
// Data driven: add another entry and the pet will settle on the first, then
// slide down to the next. One entry means it simply drops in and walks.
const INTRO_STEPS = [{ sel: ".jarvis-cta", walk: 5000 }];
const INTRO_PATHS = ["/", "/home"];
const SLIDE_SPEED = 230; // px/s down the hero onto the call to action

// A stride cycle should cover roughly one body length, or the feet skate.
const strideMs = (speed, bodyPx) =>
  clamp((bodyPx / Math.max(6, speed)) * 620, 240, 1400);

const Pet = ({ theme: themeProp, suspended = false, onDisable }) => {
  const themeFromContext = useTheme();
  const theme = themeProp || themeFromContext;
  const isLight = theme?.name === "light";

  const location = useLocation();
  const pathRef = useRef(location.pathname);

  const { w: W, h: H } = SIZE;

  const motionReduce =
    typeof window !== "undefined" &&
    window.matchMedia &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  const [pose, setPose] = useState(motionReduce ? MODE.SIT : MODE.FALL);
  // "profile" = looking where it is going; "front" = it has noticed you.
  const [look, setLook] = useState("profile");
  const blinkRef = useRef({ start: -9999, next: 0, lid: 0 });
  const [say, setSay] = useState(null);
  // The hover hint is separate from `say` on purpose: `say` is a blurt with a
  // 2.1s fuse, and this one has to stay up for exactly as long as the cursor
  // is on the pet.
  const [hint, setHint] = useState(false);
  const [engaged, setEngaged] = useState(false);

  const layerRef = useRef(null);
  const bubbleRef = useRef(null);
  const pupilRef = useRef(null);
  const mouthRef = useRef(null);

  const ledgesRef = useRef([]);
  const pointerRef = useRef({ x: 0, y: 0 });
  const lookRef = useRef({ x: 0, y: 0, vx: 0, vy: 0 });
  const mouthOpenRef = useRef(0);
  const sayTimerRef = useRef(null);
  const hintTimerRef = useRef(null);
  // The hint is a one-time teaching aid, not a tooltip: it retires for good
  // the first time someone actually drags the pet (they know now), and caps
  // itself at HINT_MAX showings per page load for everyone else -- the pet
  // wanders under a resting cursor often enough that an uncapped hover hint
  // fires over and over on its own.
  const hintsLeftRef = useRef(HINT_MAX);
  const hintDoneRef = useRef(false);
  // When the cursor last actually moved. The pet wanders, so most "hovers"
  // are the pet walking under a cursor that has been parked for a minute --
  // those are not someone looking at it, and they were what burned through
  // the budget before anyone deliberately pointed at it.
  const pointerMovedAtRef = useRef(0);

  // Half the current bubble's width, for the edge clamp in the rAF loop.
  // Measured when the content changes rather than read per frame, so the loop
  // never forces a layout. 96 is the old hardcoded value, kept as the value
  // before anything has been said.
  const bubbleHalfRef = useRef(96);
  const poseRef = useRef(pose);
  const lookRefMode = useRef("profile");
  const awareRef = useRef(false);
  const engagedRef = useRef(false);

  // Dynamic squash & stretch factor for organic landings and jumps
  const squishRef = useRef({ val: 1, target: 1, vel: 0 });

  // What the brain is doing, written by the brain and read by the loop.
  const signalRef = useRef({ state: "idle", intensity: 0 });

  // Simulation physics state
  const S = useRef({
    x: 0,
    y: 0,
    vx: 0,
    vy: 0,
    mode: MODE.FALL,
    dir: 1,
    surface: SURFACE.AIR,
    until: 0,
    ledge: null,
    wall: 0,
    boredom: 0,
    last: 0,
    rot: 0,
    scrollY: 0,
    grab: null,
    ignoreEl: null,
    ignoreUntil: 0,
    nextPerchLine: 0,
    intro: null,
    velLag: 0,
    earLag: 0,
    prevX: 0,
    prevY: 0,
    vyLag: 0,
    lastFlip: 1,
    // Tail springs (deg, deg/s): base about the rump, tip about the joint.
    tail: 0,
    tailV: 0,
    tip: 0,
    tipV: 0,
    // Head tilt spring (deg) and which way the curious tilt leans.
    tilt: 0,
    tiltV: 0,
    tiltSide: 1,
    tiltFlipAt: 0,
    excitedUntil: 0,
  });

  const setPoseSafe = useCallback((next) => {
    if (poseRef.current === next) return;
    poseRef.current = next;
    setPose(next);
  }, []);

  const setLookSafe = useCallback((next) => {
    if (lookRefMode.current === next) return;
    lookRefMode.current = next;
    setLook(next);
  }, []);

  const blurt = useCallback((text) => {
    setSay(text);
    if (sayTimerRef.current) clearTimeout(sayTimerRef.current);
    sayTimerRef.current = setTimeout(() => setSay(null), 2100);
  }, []);

  useEffect(() => () => clearTimeout(sayTimerRef.current), []);

  /* ---------------- world ---------------- */
  // Show a friendly onboarding hint 1.5 seconds after mounting
  useEffect(() => {
    const timer = setTimeout(() => {
      blurt("Drag me around or click to chat! 🐾");
    }, 1600);
    return () => clearTimeout(timer);
  }, [blurt]);
  const rescan = useCallback(() => {
    ledgesRef.current = scanLedges(
      window.innerWidth,
      window.innerHeight,
      MARGIN
    );
  }, []);

  useEffect(() => {
    rescan();
    let t;
    const debounced = () => {
      clearTimeout(t);
      t = setTimeout(rescan, 220);
    };
    const interval = setInterval(rescan, RESCAN_MS);
    window.addEventListener("scroll", debounced, { passive: true });
    window.addEventListener("resize", debounced);
    return () => {
      clearTimeout(t);
      clearInterval(interval);
      window.removeEventListener("scroll", debounced);
      window.removeEventListener("resize", debounced);
    };
  }, [rescan]);

  // The page underneath just swapped: every ledge the pet knew about belonged
  // to the old route, so drop it and re-read the furniture as the new one
  // renders (React and the lazy chunks take a few hundred ms to settle).
  useEffect(() => {
    const path = location.pathname;
    if (pathRef.current === path) return undefined;
    pathRef.current = path;

    const st = S.current;
    if (st.surface === SURFACE.LEDGE) {
      st.surface = SURFACE.AIR;
      st.ledge = null;
      if (st.mode !== MODE.DRAG && !engagedRef.current) st.mode = MODE.FALL;
    }

    const timers = [0, 400, 1200].map((d) => setTimeout(rescan, d));
    if (!engagedRef.current && !motionReduce) {
      timers.push(setTimeout(() => blurt(sayOneOf(pageReaction(path))), 900));
    }
    return () => timers.forEach(clearTimeout);
  }, [location.pathname, rescan, blurt, motionReduce]);

  // Arm the scripted arrival once the hero has actually rendered. Polls rather
  // than assuming, and gives up quietly if the anchor never shows -- then the
  // pet simply falls in and behaves normally.
  const introArmedRef = useRef(false);
  useEffect(() => {
    if (motionReduce || introArmedRef.current) return undefined;
    const path = location.pathname.replace(/\/+$/, "") || "/";
    if (!INTRO_PATHS.includes(path)) return undefined;

    let tries = 0;
    let timer;
    const arm = () => {
      const el = document.querySelector(INTRO_STEPS[0].sel);
      const r = el && el.getBoundingClientRect();
      if (r && r.width > 60 && r.top > 40 && r.top < window.innerHeight - 60) {
        introArmedRef.current = true;
        const st = S.current;
        st.x = clamp(
          r.left + r.width / 2,
          MARGIN + W / 2,
          window.innerWidth - MARGIN - W / 2
        );
        st.y = Math.max(-60, r.top - 240);
        st.vx = 0;
        st.vy = 0;
        st.dir = -1;
        st.mode = MODE.FALL;
        st.surface = SURFACE.AIR;
        st.ledge = null;
        st.intro = { idx: 0, phase: "drop", until: 0, rect: null, wantX: 0 };
        return;
      }
      tries += 1;
      if (tries < 25) timer = setTimeout(arm, 200);
    };
    timer = setTimeout(arm, 250);
    return () => clearTimeout(timer);
  }, [location.pathname, motionReduce, W]);

  // Initial placement
  useEffect(() => {
    const st = S.current;
    st.x = rand(window.innerWidth * 0.25, window.innerWidth * 0.75);
    st.y = motionReduce ? window.innerHeight - MARGIN : -40;
    st.dir = Math.random() < 0.5 ? -1 : 1;
    if (motionReduce) {
      st.mode = MODE.SIT;
      st.surface = SURFACE.FLOOR;
      st.until = Infinity;
    }
    // Paint once here rather than waiting for the first animation frame. The
    // RAF loop bails out while document.hidden, so a tab that is restored or
    // opened in the background would otherwise show the pet parked at the
    // layer origin in the top-left corner.
    const el = layerRef.current;
    if (el) {
      el.style.transform = `translate3d(${st.x - W / 2}px, ${
        st.y - H * FOOT
      }px, 0)`;
    }
  }, [motionReduce, W, H]);

  /* ---------------- interruption ---------------- */

  const engage = useCallback(() => {
    const st = S.current;
    st.boredom = 0;
    if (engagedRef.current) {
      blurt(sayOneOf(REACTIONS.pestered));
      return;
    }
    engagedRef.current = true;
    setEngaged(true);
    setSay(null);
    st.vx = 0;
    st.until = Infinity;

    const grounded =
      st.surface === SURFACE.FLOOR || st.surface === SURFACE.LEDGE;
    if (grounded) {
      st.mode = MODE.TALK;
      squishRef.current.val = 1.12; // gentle excited bounce
      return;
    }
    // Poked while airborne, on a wall or hanging from the ceiling: TALK has no
    // gravity, so going straight there would strand it in empty space. Drop
    // first -- the landing branch promotes to TALK because engagedRef is set.
    st.mode = MODE.FALL;
    st.surface = SURFACE.AIR;
    st.ledge = null;
    st.wall = 0;
    st.rot = 0;
    if (st.vy < 0) st.vy = 0;
  }, [blurt]);

  const dismiss = useCallback(() => {
    engagedRef.current = false;
    setEngaged(false);
    const st = S.current;
    st.mode = MODE.SIT;
    st.until = performance.now() + 900;
  }, []);

  useEffect(() => {
    if (suspended && engagedRef.current) dismiss();
  }, [suspended, dismiss]);

  /* ---------------- hover hint ----------------
     `cursor: grab` and a 2.1s blurt on arrival were the only signals that the
     pet can be picked up, and visitors were missing both -- so the one moment
     we know a person is looking straight at it, it says so itself. Mouse only:
     on touch, pointerenter fires as part of the tap that opens the chat, so
     the hint would flash for a frame on the way to the panel. */
  const clearHint = useCallback(() => {
    clearTimeout(hintTimerRef.current);
    hintTimerRef.current = null;
    setHint(false);
  }, []);

  const onPointerEnter = useCallback((e) => {
    if (e.pointerType && e.pointerType !== "mouse") return;
    if (engagedRef.current || S.current.grab) return;
    if (hintDoneRef.current || hintsLeftRef.current <= 0) return;
    clearTimeout(hintTimerRef.current);
    // A beat's delay, so a cursor crossing the pet on its way somewhere else
    // does not spend one of the showings.
    hintTimerRef.current = setTimeout(() => {
      if (hintDoneRef.current || hintsLeftRef.current <= 0) return;
      // The pet came to the cursor, not the other way round: no one is
      // looking, so do not spend a showing on it.
      if (performance.now() - pointerMovedAtRef.current > 900) return;
      hintsLeftRef.current -= 1;
      setHint(true);
    }, 320);
  }, []);

  // Someone who has dragged the pet before does not need telling again.
  useEffect(() => {
    try {
      if (window.localStorage.getItem(HINT_SEEN_KEY))
        hintDoneRef.current = true;
    } catch (err) {
      /* private mode: the hint just falls back to the per-load cap */
    }
    return () => clearTimeout(hintTimerRef.current);
  }, []);

  const retireHint = useCallback(() => {
    hintDoneRef.current = true;
    try {
      window.localStorage.setItem(HINT_SEEN_KEY, "1");
    } catch (err) {
      /* nothing to do -- the in-memory flag still holds for this load */
    }
  }, []);

  const onPointerDown = useCallback((e) => {
    clearTimeout(hintTimerRef.current);
    hintTimerRef.current = null;
    setHint(false);
    const st = S.current;
    try {
      e.currentTarget.setPointerCapture?.(e.pointerId);
    } catch (err) {
      /* fallback to window listeners */
    }
    st.grab = {
      id: e.pointerId,
      t0: performance.now(),
      sx: e.clientX,
      sy: e.clientY,
      offX: st.x - e.clientX,
      offY: st.y - e.clientY,
      moved: false,
    };
    pointerRef.current = { x: e.clientX, y: e.clientY };
    st.mode = MODE.DRAG;
    st.surface = SURFACE.AIR;
    st.ledge = null;
    st.boredom = 0;
    squishRef.current.val = 0.88; // scruff stretch
  }, []);

  useEffect(() => {
    const onMove = (e) => {
      const p = pointerRef.current;
      if (p.x !== e.clientX || p.y !== e.clientY) {
        pointerMovedAtRef.current = performance.now();
      }
      pointerRef.current = { x: e.clientX, y: e.clientY };
      const st = S.current;
      if (!st.grab) return;
      if (
        Math.abs(e.clientX - st.grab.sx) > TAP_SLOP ||
        Math.abs(e.clientY - st.grab.sy) > TAP_SLOP
      ) {
        // Only now is this a drag rather than a tap, so only now does it
        // complain -- a plain click used to flash "put me down!" first.
        if (!st.grab.moved) {
          blurt(sayOneOf(REACTIONS.grabbed));
          retireHint();
        }
        st.grab.moved = true;
      }
    };

    const onUp = () => {
      const st = S.current;
      const g = st.grab;
      if (!g) return;
      st.grab = null;

      const held = performance.now() - g.t0;
      if (!g.moved && held < TAP_MS) {
        st.vx = 0;
        st.vy = 0;
        st.mode = MODE.FALL;
        engage();
        return;
      }

      st.vx = clamp(st.vx * PHYS.throwScale, -PHYS.maxThrow, PHYS.maxThrow);
      st.vy = clamp(st.vy * PHYS.throwScale, -PHYS.maxThrow, PHYS.maxThrow);
      st.mode = MODE.FALL;
      if (Math.hypot(st.vx, st.vy) > 420) blurt(sayOneOf(REACTIONS.thrown));
    };

    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
  }, [blurt, engage, retireHint]);

  /* ---------------- the simulation ---------------- */

  useEffect(() => {
    if (motionReduce) {
      const st = S.current;
      const el = layerRef.current;
      if (el) {
        el.style.transform = `translate3d(${st.x - W / 2}px, ${
          st.y - H * FOOT
        }px, 0)`;
      }
      return undefined;
    }

    let raf = 0;

    const step = (now) => {
      raf = requestAnimationFrame(step);

      const st = S.current;
      const dt = st.last ? Math.min(0.034, (now - st.last) / 1000) : 0.016;
      st.last = now;
      if (document.hidden) return;

      const vw = window.innerWidth;
      const vh = window.innerHeight;
      const floorY = vh - MARGIN;
      const ceilY = MARGIN + 2;
      const minX = MARGIN + W / 2;
      const maxX = vw - MARGIN - W / 2;
      const ledges = ledgesRef.current;

      // Spring calculation for organic squash & stretch
      const sq = squishRef.current;
      const sqForce = (sq.target - sq.val) * 160;
      sq.vel = (sq.vel + sqForce * dt) * Math.max(0, 1 - 12 * dt);
      sq.val += sq.vel * dt;

      // A route change or a re-render can remove the element the pet is
      // standing on. Without this it keeps floating where the furniture used
      // to be until the next 4s rescan happens to notice.
      if (st.ledge && st.ledge.el && !st.ledge.el.isConnected) {
        st.ledge = null;
        if (st.surface === SURFACE.LEDGE) {
          st.surface = SURFACE.AIR;
          if (st.mode !== MODE.DRAG && !engagedRef.current) st.mode = MODE.FALL;
        }
      }

      // ---- scripted arrival director ----
      if (st.intro) {
        const step = INTRO_STEPS[st.intro.idx];
        const el = step && document.querySelector(step.sel);
        const r = el && el.isConnected ? el.getBoundingClientRect() : null;
        const usable = r && r.width > 60 && r.top > ceilY && r.top < floorY;

        if (!usable || st.mode === MODE.DRAG || engagedRef.current) {
          // Anchor scrolled away, or the visitor picked the pet up. Either way
          // the script stops mattering; hand straight back to the planner.
          st.intro = null;
        } else {
          st.intro.rect = { x1: r.left + 10, x2: r.right - 10, y: r.top, el };
          // Keep the live ledge in step with the anchor as the page scrolls.
          if (st.surface === SURFACE.LEDGE && st.ledge && st.ledge.el === el) {
            st.ledge = st.intro.rect;
          }

          if (st.intro.phase === "dwell" && now > st.intro.until) {
            st.intro.phase = "slide";
            st.surface = SURFACE.AIR;
            st.ledge = null;
            st.vx = 0;
            st.vy = 0;
            // Pose only -- the slide branch below bypasses the switch, so no
            // gravity is applied; this just stops it sliding down sitting up.
            st.mode = MODE.FALL;
          } else if (st.intro.phase === "patrol" && now > st.intro.until) {
            st.intro = null; // hand back to the ordinary planner
          }
        }
      }

      // Follow page scroll furniture
      if (window.scrollY !== st.scrollY) {
        st.scrollY = window.scrollY;
        if (st.ledge && st.ledge.el && st.ledge.el.isConnected) {
          const r = st.ledge.el.getBoundingClientRect();
          st.ledge.y = r.top;
          st.ledge.x1 = r.left + 6;
          st.ledge.x2 = r.right - 6;
          if (
            st.surface === SURFACE.LEDGE &&
            st.ledge.y > ceilY &&
            st.ledge.y < floorY
          ) {
            st.y = st.ledge.y;
          } else if (st.surface === SURFACE.LEDGE) {
            st.surface = SURFACE.AIR;
            st.ledge = null;
            st.mode = MODE.FALL;
          }
        }
      }

      const sliding = st.intro && st.intro.phase === "slide";
      if (sliding) {
        const target = INTRO_STEPS[st.intro.idx + 1];
        const tEl = target && document.querySelector(target.sel);
        const tr = tEl && tEl.isConnected ? tEl.getBoundingClientRect() : null;

        if (!tr || tr.width < 60) {
          st.intro = null; // anchor vanished mid-slide; just fall
          st.mode = MODE.FALL;
        } else {
          const toX = clamp(tr.left + tr.width / 2, minX, maxX);
          const toY = tr.top;
          const dx = toX - st.x;
          const dy = toY - st.y;
          const dist = Math.hypot(dx, dy) || 1;
          st.dir = dx >= 0 ? 1 : -1;
          st.rot += (0 - st.rot) * Math.min(1, 8 * dt);

          if (dist <= SLIDE_SPEED * dt + 2) {
            // Arrived: settle onto the button and walk along it.
            st.x = toX;
            st.y = toY;
            st.vx = 0;
            st.vy = 0;
            st.rot = 0;
            st.surface = SURFACE.LEDGE;
            st.ledge = {
              x1: tr.left + 10,
              x2: tr.right - 10,
              y: tr.top,
              el: tEl,
            };
            st.intro.idx += 1;
            st.intro.phase = "patrol";
            st.intro.until = now + (target.walk || 5000);
            st.mode = MODE.WALK;
            st.until = st.intro.until;
            squishRef.current.val = 1.16; // small landing squash
          } else {
            st.x += (dx / dist) * SLIDE_SPEED * dt;
            st.y += (dy / dist) * SLIDE_SPEED * dt;
          }
        }
      } else
        switch (st.mode) {
          case MODE.DRAG: {
            const g = st.grab;
            if (!g) break;
            const tx = pointerRef.current.x + g.offX;
            const ty = pointerRef.current.y + g.offY;
            const k = Math.min(1, dt / PHYS.dragLag);
            const nx = clamp(st.x + (tx - st.x) * k, minX, maxX);
            const ny = clamp(st.y + (ty - st.y) * k, ceilY + H * 0.2, floorY);

            st.vx = (nx - st.x) / dt;
            st.vy = (ny - st.y) / dt;
            st.x = nx;
            st.y = ny;
            st.rot = clamp(st.vx * 0.024, -32, 32);
            if (Math.abs(st.vx) > 30) st.dir = st.vx > 0 ? 1 : -1;
            break;
          }

          case MODE.FALL: {
            st.vy = Math.min(PHYS.terminal, st.vy + PHYS.gravity * dt);
            st.vx *= Math.max(0, 1 - PHYS.airDrag * dt);
            const prevY = st.y;
            st.x += st.vx * dt;
            st.y += st.vy * dt;
            st.rot += (0 - st.rot) * Math.min(1, 6 * dt);
            if (Math.abs(st.vx) > 20) st.dir = st.vx > 0 ? 1 : -1;

            if (st.x <= minX || st.x >= maxX) {
              const left = st.x <= minX;
              st.x = left ? minX : maxX;
              st.vx = -st.vx * PHYS.bounce;
              if (Math.abs(st.vx) < 90) {
                st.mode = MODE.CLIMB;
                st.wall = left ? -1 : 1;
                st.surface = left ? SURFACE.WALL_L : SURFACE.WALL_R;
                st.y = clamp(st.y, ceilY + W / 2 + 2, floorY - W / 2 - 2);
                st.vy = 0;
                st.dir = -1;
                st.until = now + rand(1200, 2600);
                break;
              }
            }

            if (st.vy < -260 && st.y - H * 0.85 <= ceilY) {
              st.y = ceilY;
              st.vx = 0;
              st.vy = 0;
              st.mode = MODE.CEILING;
              st.surface = SURFACE.CEILING;
              st.until = now + rand(1600, 3400);
              blurt(sayOneOf(REACTIONS.stuck));
              break;
            }

            const skipEl = now < st.ignoreUntil ? st.ignoreEl : null;
            let ledge = supportAt(ledges, st.x, prevY, st.y, skipEl);
            // The script lands on its own anchors, which are not necessarily
            // things scanLedges would accept (the hero name is a span).
            const ir =
              st.intro && st.intro.phase === "drop" ? st.intro.rect : null;
            if (
              ir &&
              st.x >= ir.x1 &&
              st.x <= ir.x2 &&
              ir.y >= prevY - 0.5 &&
              ir.y <= st.y &&
              (!ledge || ir.y < ledge.y)
            ) {
              ledge = ir;
            }
            const hitFloor = st.y >= floorY;
            if (ledge || hitFloor) {
              const onLedge = ledge && (!hitFloor || ledge.y <= floorY);
              st.y = onLedge ? ledge.y : floorY;
              st.ledge = onLedge ? ledge : null;
              st.surface = onLedge ? SURFACE.LEDGE : SURFACE.FLOOR;

              // Landing impact squash
              if (st.vy > 180) {
                squishRef.current.val = clamp(1 + st.vy * 0.00045, 1.08, 1.32);
              }
              if (st.vy > 850 && !st.intro) {
                blurt(sayOneOf(REACTIONS.landed));
              } else if (
                onLedge &&
                !st.intro &&
                now > st.nextPerchLine &&
                Math.random() < 0.5
              ) {
                // Name the thing it has settled on, so the pet reads as part of
                // whichever page it happens to be wandering.
                const what = describePerch(ledge.el);
                if (what) {
                  st.nextPerchLine = now + 14000;
                  blurt(sayOneOf(REACTIONS.perched).replace("%s", what));
                }
              }
              st.vy = 0;
              st.vx *= 0.25;
              st.rot = 0;
              st.mode = engagedRef.current ? MODE.TALK : MODE.LAND;
              st.until = now + 300;

              if (st.intro && st.intro.phase === "drop" && onLedge) {
                const step = INTRO_STEPS[st.intro.idx];
                if (INTRO_STEPS[st.intro.idx + 1]) {
                  // More anchors to visit: settle, then slide down to the next.
                  st.intro.phase = "dwell";
                  st.intro.until = now + (step.dwell || 1500);
                  st.mode = MODE.SIT;
                  st.until = st.intro.until + 400;
                } else {
                  // Final anchor: walk along it, then hand back to the planner.
                  st.intro.phase = "patrol";
                  st.intro.until = now + (step.walk || 5000);
                  st.mode = MODE.WALK;
                  st.until = st.intro.until;
                }
              }
            }
            break;
          }

          case MODE.CLIMB: {
            const wallX = st.wall < 0 ? MARGIN : vw - MARGIN;
            const reach = W / 2;
            st.x += (wallX - st.x) * Math.min(1, 9 * dt);
            st.y += st.dir * PHYS.climb * dt;
            st.rot = st.wall < 0 ? 90 : -90;

            // Only the direction of travel can end the climb. In a corner the
            // pet is touching both the ceiling and the floor-or-wall limit at
            // once, and checking both ends every frame let CLIMB and CEILING
            // hand it back and forth each frame -- a 90/180 degree flicker.
            if (st.dir < 0 && st.y - reach <= ceilY) {
              st.y = ceilY;
              // Step clear of the wall limit, or CEILING sees x <= minX on its
              // first frame and sends it straight back down the wall.
              st.x = st.wall < 0 ? minX + 1 : maxX - 1;
              st.mode = MODE.CEILING;
              st.surface = SURFACE.CEILING;
              st.dir = st.wall < 0 ? 1 : -1;
              st.until = now + rand(1800, 3600);
              break;
            }
            if (st.dir > 0 && st.y + reach >= floorY) {
              st.y = floorY;
              st.x = st.wall < 0 ? minX : maxX;
              st.rot = 0;
              st.mode = MODE.LAND;
              st.surface = SURFACE.FLOOR;
              st.wall = 0;
              st.until = now + 260;
              break;
            }
            if (now > st.until) {
              const next = planNext({
                surface: st.surface,
                boredom: st.boredom,
              });
              if (next.mode === MODE.FALL) {
                st.mode = MODE.FALL;
                st.surface = SURFACE.AIR;
                st.rot = 0;
                st.x = st.wall < 0 ? minX : maxX;
                st.vx = st.wall < 0 ? 60 : -60;
                st.vy = 0;
                st.wall = 0;
              } else {
                st.dir = next.dir;
                st.until = now + next.ms;
              }
            }
            break;
          }

          case MODE.CEILING: {
            st.y += (ceilY - st.y) * Math.min(1, 9 * dt);
            st.x += st.dir * PHYS.crawl * dt;
            st.rot = 180;

            if (st.x <= minX || st.x >= maxX) {
              st.x = clamp(st.x, minX, maxX);
              st.wall = st.x <= minX ? -1 : 1;
              st.mode = MODE.CLIMB;
              st.surface = st.wall < 0 ? SURFACE.WALL_L : SURFACE.WALL_R;
              st.dir = 1;
              st.until = now + rand(1200, 2400);
              break;
            }
            if (now > st.until) {
              const next = planNext({
                surface: st.surface,
                boredom: st.boredom,
              });
              if (next.mode === MODE.FALL) {
                st.mode = MODE.FALL;
                st.surface = SURFACE.AIR;
                st.rot = 0;
                st.vy = 20;
                st.wall = 0;
              } else {
                st.dir = next.dir != null ? next.dir : st.dir;
                st.until = now + next.ms;
              }
            }
            break;
          }

          case MODE.WALK: {
            st.rot = 0;
            st.x += st.dir * PHYS.walk * dt;

            if (st.surface === SURFACE.LEDGE && st.ledge) {
              const past = st.x < st.ledge.x1 || st.x > st.ledge.x2;
              if (past) {
                if (Math.random() < 0.6) {
                  st.dir *= -1;
                  st.x = clamp(st.x, st.ledge.x1, st.ledge.x2);
                } else {
                  st.mode = MODE.FALL;
                  st.surface = SURFACE.AIR;
                  st.ledge = null;
                  st.vx = st.dir * 30;
                  st.vy = 0;
                }
              }
            } else if (st.x <= minX || st.x >= maxX) {
              st.x = clamp(st.x, minX, maxX);
              if (Math.random() < 0.45) {
                st.wall = st.x <= minX ? -1 : 1;
                st.mode = MODE.CLIMB;
                st.surface = st.wall < 0 ? SURFACE.WALL_L : SURFACE.WALL_R;
                st.y = clamp(st.y, ceilY + W / 2 + 2, floorY - W / 2 - 2);
                st.dir = -1;
                st.until = now + rand(1400, 3000);
                break;
              }
              st.dir *= -1;
            }

            if (now > st.until) {
              // Decay rather than reset: a hard reset here meant boredom needed
              // four consecutive non-walk poses to reach SLEEP (~10% of the time).
              st.boredom = Math.max(0, st.boredom - 1);
              const next = planNext({
                surface: st.surface,
                boredom: st.boredom,
                nearWall: st.x < minX + 120 || st.x > maxX - 120,
              });
              applyPlan(st, next, now);
            }
            break;
          }

          case MODE.LAND: {
            if (now > st.until) {
              st.mode = MODE.WALK;
              st.until = now + rand(1800, 4200);
            }
            break;
          }

          case MODE.TALK: {
            st.rot += (0 - st.rot) * Math.min(1, 8 * dt);
            break;
          }

          default: {
            // planNext can choose a pause while hanging from the ceiling; it
            // stays upside down for that rather than standing up in mid-air.
            st.rot = st.surface === SURFACE.CEILING ? 180 : 0;
            if (st.surface === SURFACE.LEDGE && st.ledge) {
              if (st.x < st.ledge.x1 - 4 || st.x > st.ledge.x2 + 4) {
                st.mode = MODE.FALL;
                st.surface = SURFACE.AIR;
                st.ledge = null;
                break;
              }
            }
            if (now > st.until) {
              st.boredom += 1;
              const next = planNext({
                surface: st.surface,
                boredom: st.boredom,
                nearWall: st.x < minX + 120 || st.x > maxX - 120,
              });
              applyPlan(st, next, now);
            }
            break;
          }
        }

      /* ---- paint ---- */

      const el = layerRef.current;
      if (el) {
        let flip = st.dir >= 0 ? 1 : -1;
        if (st.mode === MODE.CLIMB) flip = st.wall < 0 ? -1 : 1;
        else if (st.mode === MODE.CEILING) flip = st.dir >= 0 ? -1 : 1;

        el.style.transform =
          `translate3d(${(st.x - W / 2).toFixed(2)}px, ${(
            st.y -
            H * FOOT
          ).toFixed(2)}px, 0)` + ` rotate(${st.rot.toFixed(2)}deg)`;
        // Facing lives on the sprite, not the layer, so the sleep "z"s (and any
        // future layer children) are never rendered back-to-front.
        el.style.setProperty("--flip", `${flip}`);

        // Mirroring the sprite also mirrors every baked gradient, which throws
        // the light source to the other side of the screen -- the thing that
        // makes a flipped sprite read as a sticker. Counter-mirror the
        // gradients themselves so the lit side stays put. Only on a change of
        // facing, not every frame.
        if (flip !== st.lastFlip) {
          st.lastFlip = flip;
          const grads = el.querySelectorAll(".pet-grad");
          for (let i = 0; i < grads.length; i += 1) {
            if (flip < 0) {
              // Gradient units are objectBoundingBox, so this is a unit-space
              // mirror about the shape's own centre.
              grads[i].setAttribute(
                "gradientTransform",
                "translate(1,0) scale(-1,1)"
              );
            } else {
              grads[i].removeAttribute("gradientTransform");
            }
          }
        }

        const speed =
          st.mode === MODE.WALK
            ? PHYS.walk
            : st.mode === MODE.CLIMB
            ? PHYS.climb
            : PHYS.crawl;
        el.style.setProperty("--stride", `${strideMs(speed, W * 0.55)}ms`);

        // Blink: snap shut in 70ms, ease back open over 190ms. Symmetric
        // blinks read as a mechanical shutter; real ones are lopsided.
        const bl = blinkRef.current;
        const dxC = pointerRef.current.x - st.x;
        const dyC = pointerRef.current.y - (st.y - H * 0.55);
        const nearC = Math.hypot(dxC, dyC);
        const stillFor = now - pointerMovedAtRef.current;
        if (st.mode === MODE.SLEEP) {
          bl.lid = 0; // the sleep pose draws its own closed lids
          bl.next = now + rand(900, 2600);
          bl.slow = false;
        } else if (bl.slow) {
          // The cat "slow blink": a long, soft close and a lingering hold --
          // the friendly one. Closes most of the way, not a full shut.
          const since = now - bl.start;
          if (since < 320)
            bl.lid = 0.9 * Math.sin((since / 320) * (Math.PI / 2));
          else if (since < 970) bl.lid = 0.9;
          else if (since < 1450) bl.lid = 0.9 * (1 - (since - 970) / 480);
          else {
            bl.lid = 0;
            bl.slow = false;
          }
        } else {
          // Someone has parked the cursor near it for a while: answer with a
          // slow blink now and then, instead of an ordinary one.
          if (
            now > (bl.nextSlow || 0) &&
            awareRef.current &&
            !engagedRef.current &&
            st.mode !== MODE.DRAG &&
            nearC < 220 &&
            stillFor > 1500
          ) {
            bl.slow = true;
            bl.start = now;
            bl.next = now + rand(2400, 5200);
            bl.nextSlow = now + rand(6000, 11000);
          } else if (now > bl.next) {
            bl.start = now;
            // Cats double-blink often, and hold a slow blink when relaxed.
            const relaxed = st.mode === MODE.SIT || st.mode === MODE.GROOM;
            bl.hold = relaxed && Math.random() < 0.35 ? rand(180, 420) : 0;
            bl.next = now + rand(2400, 6200);
          }
          if (!bl.slow) {
            const since = now - bl.start;
            const hold = bl.hold || 0;
            if (since < 70) bl.lid = since / 70;
            else if (since < 70 + hold) bl.lid = 1;
            else if (since < 260 + hold) bl.lid = 1 - (since - 70 - hold) / 190;
            else bl.lid = 0;
          }
        }
        // Happy squint while chatting: lids rest a third of the way down.
        const lid =
          engagedRef.current && st.mode === MODE.TALK
            ? Math.max(bl.lid, 0.32)
            : bl.lid;
        el.style.setProperty("--lid", clamp(lid, 0, 1).toFixed(3));

        // Excited pupils: a cursor darting about within reach.
        if (nearC < 170 && stillFor < 120 && st.mode !== MODE.SLEEP) {
          st.excitedUntil = now + 600;
        }
        const svg = el.querySelector(".pet-svg");
        const excited = now < st.excitedUntil ? "1" : "0";
        if (svg && svg.getAttribute("data-excited") !== excited) {
          svg.setAttribute("data-excited", excited);
        }

        // Head tilt. Looks up or down towards the cursor, and when the cursor
        // rests nearby, cocks the head to one side like a curious cat,
        // switching sides every few seconds. Sprite space, so it mirrors
        // with the facing on its own.
        let tiltWant = 0;
        const headFree =
          awareRef.current &&
          st.mode !== MODE.DRAG &&
          st.mode !== MODE.FALL &&
          st.mode !== MODE.CLIMB &&
          st.mode !== MODE.CEILING &&
          st.mode !== MODE.SLEEP;
        if (headFree) {
          const pitch = clamp(
            (Math.atan2(dyC, Math.abs(dxC) + 1) / DEG_T) * 0.18,
            -6,
            5
          );
          if (now > st.tiltFlipAt) {
            st.tiltSide = -st.tiltSide;
            st.tiltFlipAt = now + rand(2600, 5200);
          }
          tiltWant = pitch + (stillFor > 700 ? st.tiltSide * 6 : 0);
        }
        st.tiltV +=
          (40 * (tiltWant - st.tilt) - 2 * Math.sqrt(40) * 0.75 * st.tiltV) *
          dt;
        st.tilt += st.tiltV * dt;
        el.style.setProperty("--head-tilt", `${st.tilt.toFixed(2)}deg`);

        // Ear lag. Measured from actual frame-to-frame movement rather than
        // st.vx: WALK and CLIMB advance st.x directly and leave vx at zero, so
        // reading vx meant the ears never moved except mid-throw.
        const vxReal = (st.x - st.prevX) / Math.max(dt, 0.0005);
        st.prevX = st.x;
        st.velLag += (vxReal - st.velLag) * Math.min(1, 7 * dt);
        // Body-relative, so a left-facing cat lags the same way once mirrored.
        const accel = (vxReal - st.velLag) * st.dir;
        st.earLag +=
          (clamp(-accel * 0.035, -18, 18) - st.earLag) * Math.min(1, 11 * dt);
        el.style.setProperty("--ear-lag", `${st.earLag.toFixed(2)}deg`);

        // Tail physics, on top of the pose animation. The base is a damped
        // spring pushed opposite to how the body accelerates (speeding up
        // swings it back, stopping flings it forward) and streams against
        // vertical motion (up while falling, down while rising), so a landing
        // makes it dip and bounce. The tip is a looser spring kicked by the
        // base's own swing, which is what makes it whip rather than move as
        // one rigid stick. Underdamped on purpose, but gently.
        const vyReal = (st.y - st.prevY) / Math.max(dt, 0.0005);
        st.prevY = st.y;
        st.vyLag += (vyReal - st.vyLag) * Math.min(1, 10 * dt);
        const airborne = st.mode === MODE.FALL || st.mode === MODE.DRAG;
        const tailWant =
          clamp(-accel * 0.03, -22, 22) +
          (airborne ? clamp(st.vyLag * 0.022, -26, 26) : 0);
        st.tailV +=
          (70 * (tailWant - st.tail) - 2 * Math.sqrt(70) * 0.38 * st.tailV) *
          dt;
        st.tail = clamp(st.tail + st.tailV * dt, -34, 34);
        // A happy curl at the tip while it is looking at you.
        const tipWant =
          clamp(-st.tailV * 0.05, -26, 26) + (awareRef.current ? 9 : 0);
        st.tipV +=
          (55 * (tipWant - st.tip) - 2 * Math.sqrt(55) * 0.32 * st.tipV) * dt;
        st.tip = clamp(st.tip + st.tipV * dt, -38, 38);
        el.style.setProperty("--tail-lag", `${st.tail.toFixed(2)}deg`);
        el.style.setProperty("--tail-tip-lag", `${st.tip.toFixed(2)}deg`);
        el.style.setProperty(
          "--squish-x",
          `${(1 / Math.sqrt(sq.val)).toFixed(3)}`
        );
        el.style.setProperty("--squish-y", `${sq.val.toFixed(3)}`);

        // Cast the contact shadow onto whatever is actually underneath:
        // measuring to the viewport floor made the pet shadowless (and so
        // apparently weightless) the moment it perched on a card.
        let groundY = floorY;
        if (st.surface === SURFACE.LEDGE && st.ledge) {
          groundY = st.ledge.y;
        } else {
          for (let i = 0; i < ledges.length; i += 1) {
            const l = ledges[i];
            if (st.x < l.x1 || st.x > l.x2 || l.y < st.y) continue;
            if (l.y < groundY) groundY = l.y;
          }
        }
        const floorDist = Math.max(0, groundY - st.y);
        const shadowScale = clamp(1 - floorDist / 300, 0.25, 1.1);
        const shadowOp = clamp(1 - floorDist / 200, 0, 1);
        el.style.setProperty("--shadow-scale", `${shadowScale.toFixed(2)}`);
        el.style.setProperty("--shadow-op", `${shadowOp.toFixed(2)}`);
      }

      // Awareness & Gaze Calculations
      const dxP = pointerRef.current.x - st.x;
      const dyP = pointerRef.current.y - (st.y - H * 0.55);
      const distP = Math.hypot(dxP, dyP);
      const alwaysFront = st.mode === MODE.TALK || st.mode === MODE.DRAG;
      const asleep = st.mode === MODE.SLEEP;
      const aware =
        !asleep &&
        (alwaysFront || (awareRef.current ? distP < 320 : distP < 200));
      awareRef.current = aware;
      setLookSafe(aware ? "front" : "profile");

      // Smooth Gaze Spring
      const faceEl = pupilRef.current;
      if (faceEl) {
        let tx = 0;
        let ty = 0;
        if (aware) {
          const d = distP || 1;
          const reachK = Math.min(1, d / 220);
          tx = (dxP / d) * 2.5 * reachK * (st.dir >= 0 ? 1 : -1);
          ty = (dyP / d) * 2.2 * reachK;
        } else if (!asleep && st.mode !== MODE.FALL) {
          tx = 1.4;
        }

        const lk = lookRef.current;
        const fx = (tx - lk.x) * 18;
        const fy = (ty - lk.y) * 18;
        lk.vx = (lk.vx + fx * dt) * Math.max(0, 1 - 10 * dt);
        lk.vy = (lk.vy + fy * dt) * Math.max(0, 1 - 10 * dt);
        lk.x += lk.vx * dt;
        lk.y += lk.vy * dt;

        faceEl.setAttribute(
          "transform",
          `translate(${lk.x.toFixed(2)} ${lk.y.toFixed(2)})`
        );
      }

      // Lip-sync / Live Voice Tracking
      const mouth = mouthRef.current;
      if (mouth) {
        const sig = signalRef.current;
        const want =
          sig.state === "speaking" ? 1 + (sig.intensity || 0) * 4.8 : 0;
        const cur = mouthOpenRef.current;
        mouthOpenRef.current = cur + (want - cur) * (want > cur ? 0.48 : 0.18);
        mouth.setAttribute("ry", mouthOpenRef.current.toFixed(2));
      }

      // Speech Bubble Placement
      const bub = bubbleRef.current;
      if (bub) {
        let bx = st.x;
        let by = st.y - H * FOOT;
        if (st.mode === MODE.CEILING) by = st.y + H * 1.05;
        else if (st.mode === MODE.CLIMB) {
          bx = st.x + (st.wall < 0 ? H * 0.52 : -H * 0.52);
          by = st.y - W * 0.5;
        }
        // The clamp used to be a flat 96px, which fits "oof" and "rude." but
        // not the hover hint -- that one is two sentences wide, so near a
        // screen edge its left half was cut off by the viewport.
        const edge = Math.min(bubbleHalfRef.current, vw / 2);
        bx = clamp(bx, edge, vw - edge);
        by = clamp(by, 70, vh - 20);
        bub.style.transform = `translate3d(${bx.toFixed(2)}px, ${by.toFixed(
          2
        )}px, 0)`;
      }

      setPoseSafe(st.mode);
    };

    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [H, W, blurt, motionReduce, setPoseSafe, setLookSafe]);

  // Remeasure whenever what is in the bubble changes. Twice: the next frame
  // catches the common case, and a beat later catches the emoji, which lands
  // from a fallback font and can widen the line by ~30px after first paint --
  // measure once and the bubble ends up flush against the viewport edge.
  useEffect(() => {
    const measure = () => {
      const el = bubbleRef.current && bubbleRef.current.firstElementChild;
      bubbleHalfRef.current = el
        ? el.getBoundingClientRect().width / 2 + 14
        : 96;
    };
    const raf = requestAnimationFrame(measure);
    const late = setTimeout(measure, 180);
    return () => {
      cancelAnimationFrame(raf);
      clearTimeout(late);
    };
  }, [say, hint, engaged]);

  const sleeping = pose === MODE.SLEEP;
  const label = engaged
    ? `${NAME} is listening. Press Escape to dismiss.`
    : `${NAME}, a roaming companion. Click to chat, or drag around.`;

  return (
    <>
      <PetLayer ref={layerRef} w={W} h={H} data-pet-ignore>
        <PetGrab
          type="button"
          theme={theme}
          data-primary-control
          aria-label={label}
          onPointerDown={onPointerDown}
          onPointerEnter={onPointerEnter}
          onPointerLeave={clearHint}
          onPointerCancel={clearHint}
          onClick={(e) => {
            if (e.detail === 0) engage();
          }}
        >
          <PetSprite
            pose={pose}
            look={look}
            reduceMotion={motionReduce}
            eyesShut={sleeping}
            pupilRef={pupilRef}
            mouthRef={mouthRef}
            isLight={isLight}
          />
        </PetGrab>
        <VisuallyHidden aria-live="polite">{say || ""}</VisuallyHidden>
        {sleeping && !motionReduce && (
          <>
            <Zzz theme={theme} delay={0} aria-hidden="true">
              z
            </Zzz>
            <Zzz theme={theme} delay={0.9} aria-hidden="true">
              z
            </Zzz>
          </>
        )}
      </PetLayer>

      <BubbleLayer ref={bubbleRef} data-pet-ignore>
        {/* The hint outranks a blurt: someone hovering has asked a question,
            and a random "rude." landing on top of the answer helps nobody. */}
        {hint && !engaged && (
          <Bubble theme={theme} isMobile={false} aria-hidden="true">
            <HintLines>drag me anywhere · toss me aside 🐾</HintLines>
          </Bubble>
        )}
        {say && !hint && !engaged && (
          <Bubble theme={theme} isMobile={false} aria-hidden="true">
            {say}
          </Bubble>
        )}
        {engaged && !suspended && (
          <Suspense fallback={null}>
            <PetBrain
              name={NAME}
              theme={theme}
              isMobile={false}
              signalRef={signalRef}
              onDismiss={dismiss}
              onDisable={onDisable}
            />
          </Suspense>
        )}
      </BubbleLayer>
    </>
  );
};

function applyPlan(st, next, now) {
  st.mode = next.mode;
  if (next.dir != null) st.dir = next.dir;
  if (next.mode === MODE.FALL) {
    // supportAt() accepts a ledge level with the departure point, so without
    // this grace window a hop off a card re-lands on the same card next frame
    // and reads as a one-frame twitch instead of a jump.
    st.ignoreEl = st.ledge ? st.ledge.el : null;
    st.ignoreUntil = now + 340;
    st.surface = SURFACE.AIR;
    st.ledge = null;
    st.vx = st.dir * 25;
    st.vy = 40;
    st.until = 0;
  } else {
    st.until = now + next.ms;
  }
}

export default Pet;
